packages.css:
.pk-keyframes .kf-stage{position:relative;overflow:hidden;box-sizing:border-box}
.pk-keyframes .kf-stage[data-frame="true"]{border:2px dashed rgba(247,217,139,.35);border-radius:18px;background:rgba(255,248,245,.03)}
.pk-keyframes .kf-actor{position:absolute;left:0;top:0;box-sizing:border-box;transform-origin:50% 50%;display:flex;align-items:center;justify-content:center;overflow:hidden;will-change:transform,opacity,width,height;font-family:"DM Sans",system-ui,sans-serif;font-weight:700;line-height:1.1;text-align:center;white-space:nowrap}
.pk-keyframes .kf-actor[data-kind="shape"]{box-shadow:0 14px 34px rgba(0,0,0,.35)}
.pk-keyframes .kf-actor[data-kind="shape"][data-border="true"]{border:3px solid rgba(255,248,245,.4)}
.pk-keyframes .kf-actor[data-kind="text"]{overflow:visible}
.pk-keyframes .kf-actor[data-kind="image"]{overflow:hidden}
.pk-keyframes .kf-actor img{width:100%;height:100%;object-fit:contain;display:block}
.pk-keyframes .kf-ph{width:100%;height:100%;display:grid;place-items:center;background:rgba(255,248,245,.1);color:rgba(255,248,245,.6);font-size:18px}
.pk-keyframes .kf-guides{position:absolute;left:0;top:0;pointer-events:none;overflow:visible}
.pk-keyframes .kf-guides text{font:600 14px "DM Sans",system-ui,sans-serif;fill:#F7D98B}
@media (prefers-reduced-motion:reduce){
  .pk-keyframes .kf-actor{width:var(--kf-lw)!important;height:var(--kf-lh)!important;transform:var(--kf-lt)!important;opacity:var(--kf-lo)!important}
}

render.$fn:
function renderHtml(spec, h) {
  var N = function(v, d) {
    var n = Number(v);
    return isFinite(n) ? n : d;
  };
  var PR = ["x", "y", "w", "h", "opacity", "rotate", "scale"];
  var base = { x: N(spec.x0, 0), y: N(spec.y0, 0), w: N(spec.w0, 200), h: N(spec.h0, 120), opacity: N(spec.o0, 1), rotate: N(spec.r0, 0), scale: N(spec.s0, 1) };
  var keys = Array.isArray(spec.keys) ? spec.keys : [];
  function poseAt2(t) {
    var out = {};
    PR.forEach(function(p) {
      var pts = keys.filter(function(k) {
        return k && k.prop === p;
      }).map(function(k) {
        return { t: Math.max(0, N(k.t, 0)), v: N(k.value, base[p]) };
      }).sort(function(a, b) {
        return a.t - b.t;
      });
      if (!pts.length || pts[0].t > 0) pts.unshift({ t: 0, v: base[p] });
      var v = pts[pts.length - 1].v;
      for (var i = 0; i < pts.length; i++) {
        if (t <= pts[i].t) {
          v = i === 0 || pts[i].t === pts[i - 1].t ? pts[i].v : pts[i - 1].v + (pts[i].v - pts[i - 1].v) * (t - pts[i - 1].t) / (pts[i].t - pts[i - 1].t);
          break;
        }
      }
      out[p] = v;
    });
    return out;
  }
  function tf(p) {
    return "translate(" + p.x + "px," + p.y + "px) rotate(" + p.rotate + "deg) scale(" + p.scale + ")";
  }
  var first = poseAt2(0), last = poseAt2(Infinity);
  var radius = spec.shape === "circle" ? "50%" : spec.shape === "pill" ? "999px" : N(spec.radius, 22) + "px";
  var st = "width:" + Math.max(0, first.w) + "px;height:" + Math.max(0, first.h) + "px;opacity:" + first.opacity + ";transform:" + tf(first) + ";font-size:" + N(spec.fontSize, 32) + "px;color:" + h.esc(spec.color) + ";--kf-lw:" + Math.max(0, last.w) + "px;--kf-lh:" + Math.max(0, last.h) + "px;--kf-lt:" + tf(last) + ";--kf-lo:" + last.opacity;
  if (spec.kind === "shape") st += ";background:" + h.esc(spec.fill) + ";border-radius:" + radius;
  var W = N(spec.w, 900), H = N(spec.stageH, 420);
  var set = { 0: true };
  keys.forEach(function(k) {
    if (k) set[Math.max(0, N(k.t, 0))] = true;
  });
  var times = Object.keys(set).map(Number).sort(function(a, b) {
    return a - b;
  });
  var poses = times.map(function(t) {
    return { t, p: poseAt2(t) };
  });
  var cs = poses.map(function(o) {
    return [o.p.x + o.p.w / 2, o.p.y + o.p.h / 2];
  });
  var g = "";
  if (spec.guides) {
    g = '<svg class="kf-guides" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + " " + H + '"><polyline points="' + cs.map(function(c) {
      return c[0] + "," + c[1];
    }).join(" ") + '" fill="none" stroke="#F7D98B" stroke-width="2" stroke-dasharray="8 6" opacity=".7"/>';
    poses.forEach(function(o, i) {
      var p = o.p;
      g += '<g><rect x="' + (cs[i][0] - p.w * p.scale / 2) + '" y="' + (cs[i][1] - p.h * p.scale / 2) + '" width="' + Math.max(0, p.w * p.scale) + '" height="' + Math.max(0, p.h * p.scale) + '" transform="rotate(' + p.rotate + " " + cs[i][0] + " " + cs[i][1] + ')" fill="none" stroke="#F7D98B" stroke-width="1.5" stroke-dasharray="5 5" opacity=".55"/><circle cx="' + cs[i][0] + '" cy="' + cs[i][1] + '" r="5" fill="#F7D98B"/><text x="' + (cs[i][0] + 9) + '" y="' + (cs[i][1] - 9) + '">' + o.t + " ms</text></g>";
    });
    g += "</svg>";
  }
  var body = spec.kind === "image" ? spec.src ? '<img src="' + h.esc(spec.src) + '" alt="' + h.esc(spec.label) + '" draggable="false">' : '<div class="kf-ph">imagem</div>' : h.esc(spec.label);
  return '<div class="kf-stage" data-frame="' + (spec.frame ? "true" : "false") + '" style="width:' + W + "px;height:" + H + 'px">' + g + '<div class="kf-actor" data-kind="' + spec.kind + '" data-border="' + (spec.kind === "shape" && spec.border ? "true" : "false") + '" style="' + st + '">' + body + "</div></div>";
}

duration.$fn:
(spec) => {
    let total = 0;
    (Array.isArray(spec.keys) ? spec.keys : []).forEach((k) => {
      const t = Number(k && k.t);
      if (isFinite(t) && t > total) total = t;
    });
    const cycle = spec.repeat === "pingpong" ? total * 2 : total;
    const delay = Number(spec.startDelay);
    return (isFinite(delay) ? Math.max(0, delay) : 0) + cycle;
  }

runtime.$fn:
function keyframesRuntime(root, spec, api) {
  const actor = root.querySelector(".kf-actor");
  if (!actor) {
    return { play: () => void 0, final: () => void 0 };
  }
  const guides = root.querySelector(".kf-guides");
  const names = ["x", "y", "w", "h", "opacity", "rotate", "scale"];
  const num2 = (v, d) => {
    const n = Number(v);
    return isFinite(n) ? n : d;
  };
  const base = {
    x: num2(spec.x0, 0),
    y: num2(spec.y0, 0),
    w: num2(spec.w0, 200),
    h: num2(spec.h0, 120),
    opacity: num2(spec.o0, 1),
    rotate: num2(spec.r0, 0),
    scale: num2(spec.s0, 1)
  };
  const tracks = {};
  names.forEach((n) => {
    tracks[n] = [];
  });
  const keys = Array.isArray(spec.keys) ? spec.keys : [];
  keys.forEach((k) => {
    if (!k || names.indexOf(k.prop) < 0) return;
    const e = !k.ease || k.ease === "default" ? String(spec.easing || "ease-in-out") : k.ease;
    tracks[k.prop].push({ t: Math.max(0, num2(k.t, 0)), v: num2(k.value, base[k.prop]), e });
  });
  let total = 0;
  names.forEach((n) => {
    const tr = tracks[n];
    tr.sort((a, b) => a.t - b.t);
    if (!tr.length || tr[0].t > 0) tr.unshift({ t: 0, v: base[n], e: "linear" });
    total = Math.max(total, tr[tr.length - 1].t);
  });
  const bez = (x1, y1, x2, y2, x) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    const cx = 3 * x1;
    const bx = 3 * (x2 - x1) - cx;
    const ax = 1 - cx - bx;
    const cy = 3 * y1;
    const by = 3 * (y2 - y1) - cy;
    const ay = 1 - cy - by;
    const px = (t2) => ((ax * t2 + bx) * t2 + cx) * t2;
    let t = x;
    for (let i = 0; i < 8; i++) {
      const f = px(t) - x;
      if (Math.abs(f) < 1e-6) break;
      const d = (3 * ax * t + 2 * bx) * t + cx;
      if (Math.abs(d) < 1e-6) break;
      t -= f / d;
    }
    if (!(t >= 0 && t <= 1) || Math.abs(px(t) - x) > 1e-4) {
      let lo = 0;
      let hi = 1;
      t = x;
      for (let i = 0; i < 24; i++) {
        if (px(t) < x) lo = t;
        else hi = t;
        t = (lo + hi) / 2;
      }
    }
    return ((ay * t + by) * t + cy) * t;
  };
  const bounce = (p) => {
    const n = 7.5625;
    const d = 2.75;
    if (p < 1 / d) return n * p * p;
    if (p < 2 / d) return n * (p -= 1.5 / d) * p + 0.75;
    if (p < 2.5 / d) return n * (p -= 2.25 / d) * p + 0.9375;
    return n * (p -= 2.625 / d) * p + 0.984375;
  };
  const ease = (name, p) => {
    if (p <= 0) return 0;
    if (p >= 1) return 1;
    switch (name) {
      case "linear":
        return p;
      case "ease":
        return bez(0.25, 0.1, 0.25, 1, p);
      case "ease-in":
        return bez(0.42, 0, 1, 1, p);
      case "ease-out":
        return bez(0, 0, 0.58, 1, p);
      case "ease-in-out":
        return bez(0.42, 0, 0.58, 1, p);
      case "back":
        return bez(0.34, 1.56, 0.64, 1, p);
      case "bounce":
        return bounce(p);
      case "elastic":
        return Math.pow(2, -10 * p) * Math.sin((p * 10 - 0.75) * (2 * Math.PI) / 3) + 1;
      case "steps": {
        const n = Math.max(1, Math.round(num2(spec.steps, 4)));
        return Math.floor(p * n) / n;
      }
      case "custom":
        return bez(
          Math.min(1, Math.max(0, num2(spec.bz1, 0.42))),
          num2(spec.bz2, 0),
          Math.min(1, Math.max(0, num2(spec.bz3, 0.58))),
          num2(spec.bz4, 1),
          p
        );
      default:
        return bez(0.42, 0, 0.58, 1, p);
    }
  };
  const at = (name, t) => {
    const tr = tracks[name];
    if (t <= tr[0].t) return tr[0].v;
    for (let i = 1; i < tr.length; i++) {
      const a = tr[i - 1];
      const b = tr[i];
      if (t <= b.t) {
        if (b.t === a.t) return b.v;
        return a.v + (b.v - a.v) * ease(b.e, (t - a.t) / (b.t - a.t));
      }
    }
    return tr[tr.length - 1].v;
  };
  const apply = (t) => {
    const s = actor.style;
    s.width = Math.max(0, at("w", t)) + "px";
    s.height = Math.max(0, at("h", t)) + "px";
    s.opacity = String(Math.min(1, Math.max(0, at("opacity", t))));
    s.transform = "translate(" + at("x", t) + "px," + at("y", t) + "px) rotate(" + at("rotate", t) + "deg) scale(" + at("scale", t) + ")";
  };
  const play = () => {
    if (guides) guides.style.display = "none";
    apply(0);
    const delay = Math.max(0, num2(spec.startDelay, 0));
    const mode = spec.repeat;
    let t0 = -1;
    api.frame((ts) => {
      if (t0 < 0) t0 = ts;
      const t = ts - t0 - delay;
      if (t <= 0) {
        apply(0);
        return true;
      }
      if (total <= 0) {
        apply(0);
        return false;
      }
      if (mode === "loop") {
        apply(t % total);
        return true;
      }
      if (mode === "pingpong") {
        const c = t % (2 * total);
        apply(c <= total ? c : 2 * total - c);
        return true;
      }
      if (t >= total) {
        apply(total);
        return false;
      }
      apply(t);
      return true;
    });
  };
  const final = () => {
    if (guides) guides.style.display = "none";
    apply(total);
  };
  return { play, final };
}
